harness.setup:
zn "BATTERY"
set rs=##class(%SQL.Statement).%ExecDirect(,"SELECT COUNT(*) AS n FROM Battery_Interop.CaseResponse WHERE CaseId LIKE 'solver4-live-%-1__'")
if rs.%SQLCODE<0 { write "REPEAT_ERROR=",rs.%Message,! halt }
if rs.%Next(),rs.%Get("n")>0 { write "REPEAT_ERROR=round IDs already exist",! halt }
set sc=##class(Ens.Director).StopProduction()
if $SYSTEM.Status.IsError(sc) { write "REPEAT_ERROR=",$SYSTEM.Status.GetErrorText(sc),! halt }
set sc=##class(Ens.Director).StartProduction("Battery.Interop.Production")
if $SYSTEM.Status.IsError(sc) { write "REPEAT_ERROR=",$SYSTEM.Status.GetErrorText(sc),! halt }
write "REPEAT_READY",!
halt

